CREATE TABLE IF NOT EXISTS submissions(id TEXT PRIMARY KEY,created_at TEXT NOT NULL,status TEXT NOT NULL,item_json TEXT NOT NULL,rubric_version TEXT);CREATE TABLE IF NOT EXISTS captures(id TEXT PRIMARY KEY,submission_id TEXT NOT NULL,side TEXT NOT NULL,mode TEXT NOT NULL,sha256 TEXT NOT NULL,device_json TEXT,calibration_id TEXT,created_at TEXT NOT NULL);CREATE TABLE IF NOT EXISTS observations(id TEXT PRIMARY KEY,submission_id TEXT NOT NULL,capture_id TEXT NOT NULL,category TEXT NOT NULL,type TEXT,side TEXT NOT NULL,x REAL,y REAL,severity REAL,confidence REAL,reviewer_disposition TEXT NOT NULL,notes TEXT,created_at TEXT NOT NULL);CREATE TABLE IF NOT EXISTS qc_events(id TEXT PRIMARY KEY,submission_id TEXT NOT NULL,reviewer TEXT NOT NULL,action TEXT NOT NULL,reason TEXT,created_at TEXT NOT NULL);CREATE TABLE IF NOT EXISTS certificates(cert_id TEXT PRIMARY KEY,submission_id TEXT NOT NULL,grade REAL,condition_index INTEGER,rubric_version TEXT NOT NULL,sealed_at TEXT NOT NULL);